   Q('note', 'Ways to slow adaptation: variety and __________', 'gratitude', 'Another is gratitude.', 'Gratitude is the second way.', max=1),
   Q('note', 'Show the German data in a __________, not a table', 'graph', 'I\'d strongly recommend a graph for the German data', 'The tutor recommends a graph.', max=1),
